class CircuitBreaker:
    def __init__(self, threshold=3): self.threshold=threshold; self.failures=0; self.open=False
    def success(self): self.failures=0; self.open=False
    def failure(self):
        self.failures += 1
        if self.failures >= self.threshold: self.open=True

b=CircuitBreaker()
for _ in range(3): b.failure()
assert b.open
